schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/activation-framework.json",
  "title": "Activation Framework spec",
  "type": "object",
  "required": ["activation_event", "d30_validation", "baseline", "funnel", "dropoff_priorities", "experiments", "dashboard"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "event_name": {"type": "string", "pattern": "^[a-z][a-z0-9_]*$"},
    "rate": {"type": "number", "minimum": 0, "maximum": 1},
    "score": {"type": "integer", "minimum": 1, "maximum": 10},
    "group": {
      "type": "object",
      "required": ["users", "d30_retention"],
      "additionalProperties": false,
      "properties": {"users": {"type": "integer", "minimum": 1}, "d30_retention": {"$ref": "#/definitions/rate"}}
    }
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "activation_event": {
      "type": "object",
      "required": ["name", "window_days"],
      "additionalProperties": false,
      "properties": {
        "name": {"$ref": "#/definitions/event_name"},
        "window_days": {"type": "integer", "minimum": 1}
      }
    },
    "d30_validation": {
      "type": "object",
      "required": ["cohort", "performed", "not_performed", "correlational_note"],
      "additionalProperties": false,
      "properties": {
        "cohort": {"type": "string", "minLength": 4},
        "performed": {"$ref": "#/definitions/group"},
        "not_performed": {"$ref": "#/definitions/group"},
        "correlational_note": {"const": true}
      }
    },
    "baseline": {
      "type": "object",
      "required": ["data_cutoff", "cohorts"],
      "additionalProperties": false,
      "properties": {
        "data_cutoff": {"$ref": "#/definitions/date"},
        "cohorts": {
          "type": "array",
          "minItems": 4,
          "items": {
            "type": "object",
            "required": ["signup_week_start", "signups", "activated", "activation_rate"],
            "additionalProperties": false,
            "properties": {
              "signup_week_start": {"$ref": "#/definitions/date"},
              "signups": {"type": "integer", "minimum": 1},
              "activated": {"type": "integer", "minimum": 0},
              "activation_rate": {"$ref": "#/definitions/rate"}
            }
          }
        }
      }
    },
    "funnel": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["name", "status"],
        "properties": {
          "name": {"type": "string", "minLength": 2},
          "status": {"type": "string", "enum": ["instrumented", "uninstrumented"]}
        },
        "if": {"properties": {"status": {"const": "instrumented"}}},
        "then": {
          "required": ["event", "entered", "completed"],
          "additionalProperties": false,
          "properties": {
            "name": {"type": "string"},
            "status": {"const": "instrumented"},
            "event": {"$ref": "#/definitions/event_name"},
            "entered": {"type": "integer", "minimum": 0},
            "completed": {"type": "integer", "minimum": 0}
          }
        },
        "else": {
          "required": ["instrumentation_task"],
          "additionalProperties": false,
          "properties": {
            "name": {"type": "string"},
            "status": {"const": "uninstrumented"},
            "instrumentation_task": {"type": "string", "minLength": 8}
          }
        }
      }
    },
    "dropoff_priorities": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["step", "users_lost", "relative_drop"],
        "additionalProperties": false,
        "properties": {
          "step": {"type": "string", "minLength": 2},
          "users_lost": {"type": "integer", "minimum": 0},
          "relative_drop": {"$ref": "#/definitions/rate"}
        }
      }
    },
    "experiments": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["name", "funnel_step", "hypothesis", "primary_metric", "baseline_value", "ship_threshold_lift", "impact", "confidence", "ease", "ice"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "minLength": 3},
          "funnel_step": {"type": "string", "minLength": 2},
          "hypothesis": {"type": "string", "minLength": 20},
          "primary_metric": {"type": "string", "enum": ["activation_rate", "step_conversion"]},
          "baseline_value": {"$ref": "#/definitions/rate"},
          "ship_threshold_lift": {"type": "number", "exclusiveMinimum": 0, "maximum": 1},
          "impact": {"$ref": "#/definitions/score"},
          "confidence": {"$ref": "#/definitions/score"},
          "ease": {"$ref": "#/definitions/score"},
          "ice": {"type": "number", "minimum": 1, "maximum": 10}
        }
      }
    },
    "dashboard": {
      "type": "object",
      "required": ["cadence", "closed_cohorts_only", "window_days", "segment_by", "series_id"],
      "additionalProperties": false,
      "properties": {
        "cadence": {"const": "weekly"},
        "closed_cohorts_only": {"const": true},
        "window_days": {"type": "integer", "minimum": 1},
        "segment_by": {"type": "array", "minItems": 1, "items": {"type": "string"}, "contains": {"const": "acquisition_channel"}},
        "series_id": {"type": "string", "minLength": 3}
      }
    }
  }
}

output-contract.example:
{
  "activation_event": {"name": "project_created", "window_days": 7},
  "d30_validation": {
    "cohort": "signup week 2026-03-02",
    "performed": {"users": 412, "d30_retention": 0.46},
    "not_performed": {"users": 1388, "d30_retention": 0.11},
    "correlational_note": true
  },
  "baseline": {
    "data_cutoff": "2026-05-04",
    "cohorts": [
      {"signup_week_start": "2026-03-30", "signups": 1810, "activated": 407, "activation_rate": 0.225},
      {"signup_week_start": "2026-04-06", "signups": 1742, "activated": 383, "activation_rate": 0.22},
      {"signup_week_start": "2026-04-13", "signups": 1905, "activated": 438, "activation_rate": 0.23},
      {"signup_week_start": "2026-04-20", "signups": 1688, "activated": 371, "activation_rate": 0.22}
    ]
  },
  "funnel": [
    {"name": "signup", "status": "instrumented", "event": "signup_completed", "entered": 7145, "completed": 7145},
    {"name": "email verified", "status": "instrumented", "event": "email_verified", "entered": 7145, "completed": 5216},
    {"name": "workspace named", "status": "instrumented", "event": "workspace_named", "entered": 5216, "completed": 4903},
    {"name": "template picked", "status": "uninstrumented", "instrumentation_task": "GROW-118: emit template_picked from the onboarding modal"},
    {"name": "project created", "status": "instrumented", "event": "project_created", "entered": 4903, "completed": 1599}
  ],
  "dropoff_priorities": [
    {"step": "project created", "users_lost": 3304, "relative_drop": 0.674},
    {"step": "email verified", "users_lost": 1929, "relative_drop": 0.27},
    {"step": "workspace named", "users_lost": 313, "relative_drop": 0.06}
  ],
  "experiments": [
    {"name": "Sample project on first login", "funnel_step": "project created", "hypothesis": "Users who land in a pre-filled sample project create their own within the window because the empty state is the blocker.", "primary_metric": "activation_rate", "baseline_value": 0.224, "ship_threshold_lift": 0.03, "impact": 8, "confidence": 7, "ease": 8, "ice": 7.67},
    {"name": "Magic-link instead of verification code", "funnel_step": "email verified", "hypothesis": "A one-click magic link removes the code-entry step where 27 percent of signups stop.", "primary_metric": "step_conversion", "baseline_value": 0.73, "ship_threshold_lift": 0.05, "impact": 7, "confidence": 8, "ease": 6, "ice": 7.0}
  ],
  "dashboard": {
    "cadence": "weekly",
    "closed_cohorts_only": true,
    "window_days": 7,
    "segment_by": ["acquisition_channel"],
    "series_id": "activation-project_created-7d-v1"
  }
}

